import fs from "node:fs";
import path from "node:path";

const root = process.cwd();

const styleRelative =
  "artifacts/animated-effects/src/style.css";

const styleFile =
  path.join(root, styleRelative);

const marker =
  "AE_UI_PACK_15_ACTIVE_CARD_FIX_START";

function fail(message) {
  console.error("\nERROR:", message);
  process.exit(1);
}

if (!fs.existsSync(path.join(root, "pnpm-workspace.yaml"))) {
  fail("Uruchom z katalogu głównego aplikacja-turnieje-live.");
}

if (!fs.existsSync(styleFile)) {
  fail("Brak pliku: " + styleRelative);
}

const current =
  fs.readFileSync(styleFile, "utf8");

if (!current.includes("AE_UI_STABILITY_PACK_14_NATIVE_START")) {
  fail("Pack 15 wymaga wcześniej zainstalowanego UI Stability Pack 14.");
}

if (current.includes(marker)) {
  console.log("Pack 15 jest już zainstalowany.");
  process.exit(0);
}

const stamp =
  new Date()
    .toISOString()
    .replace(/[:.]/g, "-")
    .replace("T", "_")
    .replace("Z", "");

const backup =
  path.join(
    root,
    ".ae-pack-backup",
    `pack-15-active-card-${stamp}`,
    styleRelative,
  );

fs.mkdirSync(
  path.dirname(backup),
  { recursive: true },
);

fs.copyFileSync(styleFile, backup);

const css =
  Buffer.from(
    "",
    "hex",
  ).toString("utf8");

fs.writeFileSync(
  styleFile,
  current.trimEnd() +
    "\n\n" +
    css.trim() +
    "\n",
  "utf8",
);

const rollbackPath =
  path.join(
    root,
    "ae-ui-pack-15-active-card-fix-rollback.mjs",
  );

const rollback =
`import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const target = path.join(root, ${JSON.stringify(styleRelative)});
const backup = ${JSON.stringify(backup)};

if (!fs.existsSync(backup)) {
  console.error("Brak backupu:", backup);
  process.exit(1);
}

fs.copyFileSync(backup, target);
console.log("Pack 15 cofnięty.");
`;

fs.writeFileSync(
  rollbackPath,
  rollback,
  "utf8",
);

console.log("");
console.log("============================================");
console.log(" Animated Effects UI Pack 15 INSTALLED");
console.log("============================================");
console.log("");
console.log("Naprawiono:");
console.log(" - aktywna karta ma więcej miejsca na rząd - / licznik / +");
console.log(" - kontrolki nie dotykają dolnej krawędzi");
console.log(" - większy i równy odstęp między treścią a kontrolkami");
console.log(" - lepsze centrowanie i czytelność licznika");
console.log(" - większy odstęp od scrollbara biblioteki");
console.log("");
console.log("To jest wyłącznie CSS — bez MutationObserverów i zmian logiki.");
console.log("");
console.log("Backup:", path.relative(root, backup));
console.log("Rollback: .\\ae-ui-pack-15-active-card-fix-rollback.mjs");
console.log("");
console.log("Teraz:");
console.log("  pnpm --filter animated-effects run typecheck");
console.log("  pnpm --filter animated-effects run build");
